import json
with open('heatmap.html', 'r') as f:
    content = f.read()
import re
m = re.search(r'const spec = (\{.*?\});', content, re.DOTALL)
spec = json.loads(m.group(1))

# Check the data field
data = spec.get('data')
print('Data field:', list(data.keys()) if isinstance(data, dict) else type(data))
if isinstance(data, dict) and 'values' in data:
    print('Number of inline values:', len(data['values']))
    print('First few values:', data['values'][:3])

# Check datasets
datasets = spec.get('datasets', {})
print('Datasets keys:', list(datasets.keys()))
for k, v in datasets.items():
    if isinstance(v, dict) and 'values' in v:
        print(f'  {k}: {len(v[\"values\"])} values')
    else:
        print(f'  {k}: {type(v)}')

# Confirm no remote URL in data
def has_url(obj):
    if isinstance(obj, str):
        return obj.startswith('http://') or obj.startswith('https://')
    if isinstance(obj, dict):
        return any(has_url(v) for v in obj.values())
    if isinstance(obj, list):
        return any(has_url(v) for v in obj)
    return False
print('Data has URL?', has_url(data))
print('Datasets has URL?', has_url(datasets))
"

